package com.bank.transfer;

// Models the HikariCP pool. When active == max, the pool is saturated
// and the service should report NOT READY (but stays alive).
public class ConnectionPoolGauge {
    private final int max;
    private int active;

    public ConnectionPoolGauge(int max) { this.max = max; }

    public void acquire() { if (active < max) active++; }
    public void release() { if (active > 0) active--; }
    public boolean isSaturated() { return active >= max; }
    public int getActive() { return active; }
    public int getMax() { return max; }
}
