package com.bank.transfer;

import java.util.logging.Logger;

// This class is what the three Kubernetes probes effectively call.
public class TransferHealthService {

    private static final Logger log = Logger.getLogger(TransferHealthService.class.getName());

    private final ConnectionPoolGauge pool;
    private boolean started = false;    // becomes true once boot (migrations/cache) finishes
    private boolean deadlocked = false; // simulates an unrecoverable internal failure

    public TransferHealthService(ConnectionPoolGauge pool) {
        this.pool = pool;
    }

    // STARTUP PROBE: returns true only after boot completes.
    public boolean checkStartup() {
        log.fine(() -> "startup probe: started=" + started);
        return started;
    }

    // READINESS PROBE: can I take traffic right now? Depends on pool health.
    // Failing this removes the Pod from the Service endpoints (no restart).
    public boolean checkReadiness() {
        if (!started) return false;             // not ready until startup done
        boolean ready = !pool.isSaturated();
        if (!ready) {
            log.warning(() -> "READINESS DOWN: pool saturated "
                    + pool.getActive() + "/" + pool.getMax() + " — pull from Service");
        }
        return ready;
    }

    // LIVENESS PROBE: am I fundamentally alive? Trivial check, NOT downstream.
    // Failing this restarts the container.
    public boolean checkLiveness() {
        boolean alive = !deadlocked;
        if (!alive) {
            log.severe("LIVENESS DOWN: thread pool deadlocked — kubelet will restart container");
        }
        return alive;
    }

    public void finishStartup() { this.started = true; log.info("boot complete — migrations + cache warm done"); }
    public void triggerDeadlock() { this.deadlocked = true; }
    public void recover() { this.deadlocked = false; }
    public ConnectionPoolGauge getPool() { return pool; }
}
