package com.bank.transfer;

import java.math.BigDecimal;
import java.util.logging.*;

public class ProbeSimulationDemo {

    private static final Logger log = Logger.getLogger(ProbeSimulationDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        h.setLevel(Level.ALL);
        Logger root = Logger.getLogger("");
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        ConnectionPoolGauge pool = new ConnectionPoolGauge(2);
        TransferHealthService health = new TransferHealthService(pool);

        // t=0: cold start — startup probe failing, liveness/readiness suppressed by kubelet
        log.info("t=0  startup=" + health.checkStartup() + " (kubelet suppresses liveness/readiness)");

        // t=80s: boot finishes
        health.finishStartup();
        log.info("t=80 readiness=" + health.checkReadiness() + " liveness=" + health.checkLiveness());

        // Burst of transfers saturates the pool -> readiness goes DOWN, still alive
        pool.acquire(); pool.acquire();
        log.info("t=85 readiness=" + health.checkReadiness() + " (removed from Service, NOT restarted)");

        // One transfer completes -> pool frees -> readiness recovers
        pool.release();
        rajesh.debit(new BigDecimal("50000"));
        priya.credit(new BigDecimal("50000"));
        log.info("t=90 transfer SAV2001->CUR3001 Rs.50000 done; readiness=" + health.checkReadiness());

        // Internal deadlock -> liveness DOWN -> container restart
        health.triggerDeadlock();
        log.info("t=95 liveness=" + health.checkLiveness() + " (kubelet restarts container)");
    }
}
