package com.bank.transfer;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.logging.*;

public class BankLogFormatter extends Formatter {
    private static final DateTimeFormatter FMT =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSS");
    @Override
    public String format(LogRecord r) {
        String ts = LocalDateTime.ofInstant(Instant.ofEpochMilli(r.getMillis()), ZoneId.systemDefault()).format(FMT);
        String base = String.format("%s [%s] %s%n", ts, r.getLevel(), formatMessage(r));
        if (r.getThrown() != null) {
            StringBuilder sb = new StringBuilder(base);
            sb.append(r.getThrown()).append('\n');
            for (StackTraceElement e : r.getThrown().getStackTrace()) sb.append("    at ").append(e).append('\n');
            return sb.toString();
        }
        return base;
    }
}
